import java.util.*;
import java.util.concurrent.*;

public class Main {
    public static void main(String[] args) throws Exception {
        List<Callable<String>> tasks = List.of(() -> "a", () -> "b", () -> "c");
        try (var ex = Executors.newFixedThreadPool(2)) {
            var sb = new StringBuilder();
            for (Future<String> f : ex.invokeAll(tasks)) sb.append(f.get());
            IO.println(sb + " " + ex.isShutdown());
        }
    }
}

import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

public class Main {
    public static void main(String[] args) {
        var atomic = new AtomicInteger();
        try (var ex = Executors.newVirtualThreadPerTaskExecutor()) {
            for (int i = 0; i < 1000; i++) {
                ex.submit(() -> { atomic.incrementAndGet(); });
            }
        }
        IO.println(atomic.get() + " " + atomic.getAndIncrement() + " " + atomic.get());
    }
}

import java.util.concurrent.locks.*;

public class Main {
    public static void main(String[] args) {
        Lock lock = new ReentrantLock();
        if (lock.tryLock()) {
            try { IO.print("locked "); } finally { lock.unlock(); }
        }
        lock.unlock();
        IO.println("end");
    }
}

